// Pharmacology Practice Test 1. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items: drug classes by stem, mechanisms, monitoring and interactions.
import {q, mix} from './q.js';
const MOINI='Moini, The Pharmacy Technician: A Comprehensive Approach', FORD='Ford & Roach, Introductory Clinical Pharmacology', DV='Dean Vaughn’s Pharmacology by Body System';
const BASIC='Basic Concepts in Pharmacology', LEGAL='Ethical and Legal Responsibilities', AGE='Pediatrics and Geriatrics Adaptations', DRUG='Drug Names, Classifications, Actions, and Interactions', ADMIN='Drug Administration', MEAS='Drug Measurement, Dosage, Conversions', TECH='Technologies in Pharmacology';

export default {
 id:'pharmacology-1',
 event:'Pharmacology',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Moini’s The Pharmacy Technician, Ford & Roach’s Introductory Clinical Pharmacology, and Dean Vaughn’s Pharmacology',
 plan:[{area:BASIC,weight:15},{area:LEGAL,weight:10},{area:AGE,weight:10},{area:DRUG,weight:30},{area:ADMIN,weight:20},{area:MEAS,weight:10},{area:TECH,weight:5}],
 questions:mix([
  q(BASIC,'Why do some drugs need a much higher oral dose than IV dose to have the same effect?','The liver metabolizes much of the oral dose before it reaches circulation',['Oral drugs are excreted faster by the kidneys','The stomach acid inactivates every oral drug','IV drugs bind more tightly to plasma proteins'],'B','This is the first-pass effect. Drugs absorbed from the GI tract travel through the portal vein to the liver, which can metabolize a large share before it reaches the rest of the body. IV drugs skip this step.',FORD),
  q(BASIC,'A drug has a half-life of 6 hours. If 400 mg is given, how much remains in the body after 18 hours?','50 mg',['25 mg','100 mg','133 mg'],'D','18 hours is three half-lives. 400 → 200 (6 h) → 100 (12 h) → 50 mg (18 h).',FORD),
  q(BASIC,'Naloxone reverses an opioid overdose. How is naloxone classified?','An opioid antagonist that blocks the receptor',['An opioid agonist that activates the receptor','A stimulant that speeds up breathing','An enzyme that breaks down the opioid'],'A','An antagonist binds to a receptor without activating it, blocking the agonist (the opioid) from acting. Naloxone displaces opioids from their receptors and restores breathing.',FORD),
  q(BASIC,'Warfarin and digoxin are said to have a narrow therapeutic index. What does this mean?','The effective dose is close to the toxic dose',['The drug works only in a narrow age range','The drug acts on only one type of receptor','The drug is absorbed through a small area'],'C','The therapeutic index compares the toxic dose to the effective dose. When they are close together, small changes in dose or blood level can cause toxicity, so these drugs require careful monitoring.',FORD),
  q(BASIC,'Which route of administration gives a drug a bioavailability of 100%?','Intravenous',['Oral','Intramuscular','Transdermal'],'B','Bioavailability is the fraction of a dose that reaches systemic circulation. An IV dose enters the bloodstream directly, so all of it is available. Other routes lose some drug during absorption.',MOINI),
  q(BASIC,'Two drugs given together produce an effect greater than the sum of their separate effects. What is this called?','Synergism',['Antagonism','Tolerance','Potentiation of excretion'],'D','In synergism, combined drugs produce more than their added effects (1 + 1 > 2). Antagonism is when one drug reduces the effect of another.',FORD),
  q(BASIC,'A patient on long-term opioids needs higher doses to get the same pain relief. This is an example of:','Tolerance',['Physical dependence','Addiction','Idiosyncrasy'],'A','Tolerance is a reduced response to the same dose over time. Physical dependence is when withdrawal symptoms occur if the drug is stopped; addiction involves compulsive use despite harm; and an idiosyncrasy is an unusual, unexpected reaction.',FORD),
  q(LEGAL,'Oxycodone has a high potential for abuse but an accepted medical use. In which DEA schedule is it?','Schedule II',['Schedule I','Schedule III','Schedule V'],'C','Schedule II drugs have a high abuse potential and accepted medical uses, with strict prescribing rules. Schedule I drugs have no accepted medical use, and Schedules III–V have progressively lower abuse potential.',MOINI),
  q(LEGAL,'Which federal agency enforces the Controlled Substances Act and registers prescribers of controlled drugs?','Drug Enforcement Administration (DEA)',['Food and Drug Administration (FDA)','Centers for Disease Control and Prevention (CDC)','Occupational Safety and Health Administration (OSHA)'],'B','The DEA enforces controlled substance laws and issues registration numbers to prescribers and pharmacies. The FDA approves drugs as safe and effective.',MOINI),
  q(LEGAL,'Checking two patient identifiers, such as name and date of birth, before giving a medication confirms which right of medication administration?','Right patient',['Right drug','Right route','Right documentation'],'D','Two identifiers confirm the right patient. The other rights include right drug, dose, route, time and documentation.',FORD),
  q(LEGAL,'A healthcare worker realizes a patient received twice the ordered dose. What should be done first?','Assess the patient and notify the prescriber',['Complete an incident report before anything else','Wait to see whether side effects develop','Give the next dose late to balance it out'],'A','Patient safety comes first: assess the patient for effects and notify the prescriber so treatment can begin. An incident report is completed afterward and is not placed in the medical record.',FORD),
  q(LEGAL,'What is a boxed (“black box”) warning on a drug label?','The FDA’s strongest warning about serious risks',['A notice that the drug is a controlled substance','A label for drugs given only in hospitals','A warning that the drug is still experimental'],'C','A boxed warning is the FDA’s most serious label warning, used when a drug carries a risk of serious or life-threatening adverse effects.',MOINI),
  q(AGE,'Why are older adults at increased risk of drug toxicity?','Declining kidney and liver function slows drug elimination',['Older adults absorb drugs more quickly from the stomach','Older adults have more body water to dilute drugs','Aging increases the number of drug receptors'],'B','With age, kidney filtration and liver metabolism decline, so drugs and their metabolites stay in the body longer and can accumulate. Body water actually decreases with age.',FORD),
  q(AGE,'What are the Beers Criteria?','A list of medications that may be inappropriate for older adults',['Dosing rules for children based on body weight','Standards for storing controlled substances','A scale for measuring drug interactions'],'D','The American Geriatrics Society Beers Criteria identify drugs whose risks often outweigh their benefits in older adults, such as some sedatives and anticholinergic drugs.',FORD),
  q(AGE,'Why are infants more sensitive than adults to many drugs?','Their liver enzymes and kidneys are not fully developed',['They have more fat tissue to store drugs','Their stomach empties faster than an adult’s','They have fewer receptors for most drugs'],'A','Immature liver enzyme systems and kidney function slow the metabolism and elimination of drugs in infants, so drug levels can rise quickly. A less mature blood-brain barrier also lets more drug reach the brain.',FORD),
  q(AGE,'Tetracycline antibiotics are generally avoided in children under 8 years old because they can:','Permanently discolor developing teeth',['Stunt growth of the long bones','Cause hearing loss in young children','Damage the developing retina'],'C','Tetracyclines bind to calcium in developing teeth and bone, causing permanent yellow-brown tooth discoloration.',MOINI),
  q(AGE,'An older adult takes nine prescription and over-the-counter medications. What is the main risk of this polypharmacy?','More drug interactions and adverse effects',['Faster absorption of each drug','Lower cost from combined prescriptions','Improved adherence to each medication'],'B','Taking many medications increases the chance of interactions, duplications, side effects and errors, especially as organ function declines. Regular medication reviews help reduce this risk.',FORD),
  q(DRUG,'Atorvastatin, simvastatin and rosuvastatin lower cholesterol by inhibiting which enzyme?','HMG-CoA reductase',['Angiotensin-converting enzyme','Cyclooxygenase','Monoamine oxidase'],'D','The -statin drugs block HMG-CoA reductase, a key enzyme the liver uses to make cholesterol, lowering LDL levels. Muscle pain is a possible side effect.',DV),
  q(DRUG,'A patient started on lisinopril develops a persistent dry cough. Which drug class does lisinopril belong to?','ACE inhibitor',['Beta blocker','Calcium channel blocker','Angiotensin II receptor blocker'],'A','Drugs ending in -pril are ACE inhibitors. Blocking ACE also lets bradykinin build up, which can cause a dry cough. Patients who cannot tolerate it are often switched to an ARB (-sartan).',DV),
  q(DRUG,'Why is propranolol, a nonselective beta blocker, used with caution in patients with asthma?','It can cause bronchoconstriction',['It raises the heart rate dangerously','It causes severe low blood sugar','It blocks the effect of inhaled steroids'],'C','Nonselective beta blockers block beta-2 receptors in the lungs as well as beta-1 receptors in the heart, which can narrow the airways. Cardioselective drugs such as metoprolol are safer choices.',FORD),
  q(DRUG,'Omeprazole, pantoprazole and esomeprazole reduce stomach acid by:','Blocking the proton pump in parietal cells',['Neutralizing acid already in the stomach','Blocking histamine-2 receptors','Coating the stomach lining'],'B','The -prazole drugs are proton pump inhibitors; they block the final step of acid secretion. Antacids neutralize existing acid, and H2 blockers (-tidine) block histamine receptors.',DV),
  q(DRUG,'A patient on warfarin has an elevated INR and is bleeding. Which agent reverses warfarin?','Vitamin K',['Protamine sulfate','Naloxone','Flumazenil'],'D','Warfarin blocks vitamin K-dependent clotting factors and is monitored with the PT/INR. Vitamin K reverses it. Protamine sulfate reverses heparin.',FORD),
  q(DRUG,'Which lab test is used to monitor a continuous IV heparin infusion?','Activated partial thromboplastin time (aPTT)',['International normalized ratio (INR)','Hemoglobin A1c','Serum creatinine'],'A','Heparin therapy is monitored with the aPTT, and its antidote is protamine sulfate. Warfarin is monitored with the INR.',FORD),
  q(DRUG,'How does metformin lower blood glucose in type 2 diabetes?','It decreases glucose production by the liver',['It stimulates the pancreas to release insulin','It replaces the insulin the body cannot make','It blocks glucose absorption by the kidneys'],'C','Metformin, a biguanide, reduces hepatic glucose output and improves insulin sensitivity. It does not stimulate insulin release, so it rarely causes hypoglycemia on its own.',DV),
  q(DRUG,'A patient is starting levothyroxine. Which instruction is correct?','Take it on an empty stomach, 30–60 minutes before breakfast',['Take it with a large meal to prevent nausea','Take it only when feeling tired or cold','Take it at bedtime with a glass of milk'],'B','Food, calcium and iron reduce levothyroxine absorption, so it is taken on an empty stomach at the same time every day. It treats hypothyroidism and must be taken daily.',FORD),
  q(DRUG,'A patient taking furosemide should be monitored closely for which electrolyte imbalance?','Hypokalemia (low potassium)',['Hyperkalemia (high potassium)','Hypercalcemia (high calcium)','Hypernatremia (high sodium)'],'A','Furosemide is a loop diuretic that causes the kidneys to excrete sodium, water and potassium. Low potassium can cause muscle weakness and dangerous heart rhythms.',FORD),
  q(DRUG,'Why should patients taking some statins avoid large amounts of grapefruit juice?','It blocks the enzyme that breaks down the drug, raising its level',['It speeds the drug’s excretion, lowering its level','It binds the drug in the stomach and blocks absorption','It cancels the drug’s effect on cholesterol directly'],'D','Grapefruit juice inhibits the CYP3A4 enzyme in the intestine and liver. Drugs metabolized by this enzyme, such as simvastatin, can build up and cause toxicity.',MOINI),
  q(DRUG,'A patient taking a monoamine oxidase inhibitor (MAOI) eats aged cheese and cured meat. What reaction is most likely?','Hypertensive crisis',['Severe hypoglycemia','Serotonin deficiency','Respiratory depression'],'C','MAOIs prevent the breakdown of tyramine, found in aged and fermented foods. Tyramine buildup releases norepinephrine and can cause a dangerous rise in blood pressure.',FORD),
  q(DRUG,'A patient taking sertraline is also given another serotonin-boosting drug and develops agitation, fever, tremor and a rapid heart rate. What is the likely cause?','Serotonin syndrome',['Neuroleptic malignant syndrome','Anaphylaxis','Hypothyroid crisis'],'A','Sertraline is an SSRI. Combining serotonergic drugs (other antidepressants, triptans, tramadol) can cause excess serotonin activity, a potentially life-threatening reaction.',FORD),
  q(DRUG,'How do benzodiazepines such as lorazepam produce their calming effect, and which drug reverses them?','They enhance GABA; flumazenil reverses them',['They block dopamine; naloxone reverses them','They block serotonin; vitamin K reverses them','They enhance norepinephrine; atropine reverses them'],'B','Benzodiazepines (-azepam, -azolam) increase the effect of GABA, the brain’s main inhibitory neurotransmitter. Flumazenil is the benzodiazepine antagonist.',DV),
  q(DRUG,'Gentamicin, an aminoglycoside antibiotic, requires blood level monitoring mainly because it can damage which organs?','The kidneys and the inner ear',['The liver and the pancreas','The heart and the lungs','The bone marrow and the skin'],'D','Aminoglycosides are nephrotoxic and ototoxic. Peak and trough levels help keep the drug effective while limiting kidney damage and hearing loss.',FORD),
  q(DRUG,'An acetaminophen overdose threatens which organ, and what is the antidote?','The liver; acetylcysteine',['The kidneys; vitamin K','The stomach; misoprostol','The heart; atropine'],'C','A toxic metabolite of acetaminophen damages liver cells when the body’s glutathione runs out. Acetylcysteine replenishes glutathione and works best when given early.',MOINI),
  q(ADMIN,'Nitroglycerin is given sublingually during angina because this route:','Absorbs quickly into the blood and avoids first-pass metabolism',['Releases the drug slowly over several hours','Coats the esophagus to reduce chest pain','Protects the drug from the patient’s saliva'],'A','The thin mucosa under the tongue has a rich blood supply, so the drug enters circulation in minutes and bypasses the liver. Swallowing nitroglycerin would greatly reduce its effect.',FORD),
  q(ADMIN,'Which intramuscular injection site is recommended for infants?','Vastus lateralis',['Deltoid','Dorsogluteal','Ventrogluteal'],'D','The vastus lateralis, on the outer thigh, is well developed in infants and free of major nerves and vessels. The deltoid is too small for most infant injections.',FORD),
  q(ADMIN,'What is the purpose of the Z-track method of intramuscular injection?','To keep irritating drugs from leaking into the tissue above',['To lessen pain by injecting very slowly','To speed absorption by massaging the site','To allow a larger volume in a small muscle'],'B','The skin is pulled to one side before injection and released after, creating a zigzag path that seals the drug in the muscle. It is used for irritating or staining drugs such as iron dextran.',FORD),
  q(ADMIN,'At what angle is an intradermal injection, such as a tuberculin skin test, given?','10 to 15 degrees',['45 degrees','45 to 90 degrees','90 degrees'],'C','Intradermal injections are given almost parallel to the skin, at 10–15 degrees, so a small bleb forms just under the epidermis. Subcutaneous injections use 45–90 degrees, and IM injections use 90 degrees.',FORD),
  q(ADMIN,'Which type of tablet should never be crushed?','Enteric-coated tablet',['Scored tablet','Chewable tablet','Plain uncoated tablet'],'A','An enteric coating protects the drug from stomach acid (or the stomach from the drug) so it dissolves in the intestine. Crushing it destroys the coating. Extended-release products also should not be crushed.',MOINI),
  q(ADMIN,'Which practice is correct when applying a new transdermal patch?','Remove the old patch and place the new one on a different site',['Apply the new patch on top of the old one','Cut the patch in half to lower the dose','Apply heat over the patch to speed absorption'],'D','Rotating sites prevents skin irritation, and removing the old patch prevents overdose. Cutting or heating a patch can release too much drug at once.',FORD),
  q(ADMIN,'After instilling eye drops, why should gentle pressure be applied to the inner corner of the eye?','To keep the drug from draining into the nasolacrimal duct',['To spread the drug across the cornea','To stop the patient from blinking','To open the tear glands for absorption'],'B','Pressing over the nasolacrimal duct for about a minute keeps the drug in the eye and reduces absorption into the bloodstream through the nose and throat.',FORD),
  q(ADMIN,'When giving ear drops to a 2-year-old child, how should the earlobe be pulled to straighten the ear canal?','Down and back',['Up and back','Straight up','Down and forward'],'A','A young child’s ear canal is short and points upward, so the pinna is pulled down and back. For adults and children over about 3, it is pulled up and back.',FORD),
  q(ADMIN,'Which abbreviation is on The Joint Commission’s “Do Not Use” list because it is easily misread?','QD',['PRN','PO','BID'],'C','QD (daily) can be mistaken for QID (four times daily), so “daily” must be written out. Other banned abbreviations include U for units and trailing zeros such as 1.0 mg.',MOINI),
  q(ADMIN,'Why is a spacer often recommended with a metered-dose inhaler?','It helps more medication reach the lungs instead of the mouth',['It increases the dose released with each puff','It allows the inhaler to be used without shaking','It replaces the need to hold the breath afterward'],'B','A spacer holds the medication so the patient can inhale it slowly, improving delivery to the airways and reducing deposits in the mouth and throat. It is especially helpful for children and older adults.',FORD),
  q(MEAS,'Digoxin 0.125 mg is ordered. Tablets are 0.25 mg each. How many tablets should be given?','½ tablet',['¼ tablet','2 tablets','1 tablet'],'D','0.125 mg ÷ 0.25 mg per tablet = 0.5, or one-half tablet. The tablet must be scored to be split.',MOINI),
  q(MEAS,'The order is 60 mg of a liquid medication. The label reads 20 mg per 5 mL. How many mL should be given?','15 mL',['3 mL','12 mL','20 mL'],'A','Desired ÷ have × quantity: 60 mg ÷ 20 mg × 5 mL = 3 × 5 = 15 mL. Check: 15 mL contains three 20-mg portions.',MOINI),
  q(MEAS,'Levothyroxine 0.1 mg is ordered. The tablets are labeled in micrograms. Which strength matches the order?','100 mcg',['10 mcg','1 mcg','1000 mcg'],'C','1 mg = 1000 mcg, so 0.1 mg × 1000 = 100 mcg. Levothyroxine tablets are commonly labeled in micrograms.',MOINI),
  q(MEAS,'A drug is ordered at 2 mg/kg. The patient weighs 66 lb. What dose should be given?','60 mg',['30 mg','132 mg','145 mg'],'B','66 lb ÷ 2.2 = 30 kg. 30 kg × 2 mg/kg = 60 mg. Using pounds without converting gives 132 mg.',MOINI),
  q(MEAS,'One liter of IV fluid is to infuse over 10 hours. What rate in mL/hr should the pump be set to?','100 mL/hr',['10 mL/hr','60 mL/hr','166 mL/hr'],'D','Convert first: 1 L = 1000 mL. Then rate = volume ÷ time = 1000 mL ÷ 10 hr = 100 mL/hr.',MOINI),
  q(TECH,'How does barcode medication administration help prevent errors at the bedside?','It matches the patient’s wristband to the drug before it is given',['It calculates the dose from the patient’s weight','It automatically orders refills from the pharmacy','It stores controlled drugs in a locked drawer'],'B','The nurse scans the patient’s wristband and the medication barcode, and the system checks them against the order for the right patient, drug, dose and time.',MOINI),
  q(TECH,'What is the main safety benefit of computerized prescriber order entry (CPOE)?','It removes handwriting errors and checks orders for problems',['It lets patients change their own medication orders','It replaces the pharmacist’s review of each order','It sends prescriptions directly to insurance companies'],'A','Orders are typed rather than handwritten, avoiding misread handwriting, and the system can alert prescribers to allergies, interactions and dosing errors.',MOINI),
  q(TECH,'Automated dispensing cabinets on hospital units help control medications mainly by:','Tracking who removes each drug and when',['Compounding IV solutions automatically','Replacing the need for physician orders','Mixing drugs at the patient’s bedside'],'C','Cabinets such as Pyxis require a login, release only profiled medications and keep a record of every access, which improves security and inventory control, especially for controlled substances.',MOINI)
 ],31)
};
